window.RP_SESSION={"id":"S-97b47c255b2a","messages":[{"id":"RP-0012408","time":"2026-01-05T23:30:00+09:00","room":"RP","name":"헬리오스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"따뜻한 온기가 도는 대장간. 골골거리며 큰 사자는 오늘도 용광로 근처에서 몸을 말고 자고 있습니다. 푹신한 것이 딱 안기기도 편하고 따스해보이네요.\n\n자면서 중간중간 입맛을 다시고, 꼼지락거립니다.","characters":["P-d5d1b5a0c634"]},{"id":"RP-0012409","time":"2026-01-05T23:31:00+09:00","room":"RP","name":"메타 반응","profile":"루체","identity":"reviewed","type":"dialogue","body":"(데미안인데스옹","characters":[]},{"id":"RP-0012410","time":"2026-01-05T23:39:00+09:00","room":"RP","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"유난히 방에 한기가 들어 맥주 한잔을 걸치곤 멍을 때리던 그녀는 이내 그나마 온기가 퍼진듯한 대장간으로 슬며시 들어가 보았습니다.\n\n\"... 에...?\"\n\n눈앞에 놓인 거대하고 검은 털뭉치에 잠시 멈칫하였지만 이 날씨에 온기를 거부할 순 없었기에 따라 용광로 근처로 가 자리를 잡아 앉았습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-0012411","time":"2026-01-06T00:06:00+09:00","room":"RP","name":"헬리오스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"골골. 지속적으로 안정되는 소리 내며 잠들다가. 인기척에 조용히 올려다봅니다.\n\n“ 마으리아···? ”\n\n아직 잠에 젖은 듯, 웃음 보이지만 눈은 반쯤 감겨있습니다.","characters":["P-d5d1b5a0c634"]},{"id":"RP-0012413","time":"2026-01-06T00:26:00+09:00","room":"RP","name":"마리아 아나이스 에스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...ㄴ,네 마리아에요...\"\n\n그녀는 당황한듯 어설프게 웃어보였다.\n\n\"잠깐 추워서 온거라서..ㅈ주무셔요..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0012414","time":"2026-01-06T14:31:00+09:00","room":"RP","name":"헬리오스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d5d1b5a0c634"]},{"id":"RP-0012415","time":"2026-01-06T14:31:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
